// game.js - escort the train for one leg of the fixed Farmlands line. The Viper fights by itself
// or where you send it. Zombies walk in, block the rails and climb onto the train. A run ends at
// the next station or when the train breaks; collected rewards are kept. The view follows the
// train. Behind the title and Depot, a separate demo battle runs without earning rewards.
// Units are world pixels and seconds; y on the ground is squashed by FORE; the train runs to -y.

const CFG = {
  // the line: px along the rails in 1 km (2 px = 1 m)
  line: { km: 2000 },
  // the train: top speed (px/s), how fast it gets back up to speed, how hard it brakes, its health,
  // and the health it loses for each zombie it runs over (a brute costs more)
  train: { cruise: 40, accel: 14, brake: 16, hp: 80, crush: 0.5, crushBig: 6 },
  // a helicopter: its top speed, how fast it gets there, how near loot must be to pick it up
  heli: { speed: 170, accel: 3.2, pickup: 14 },
  // 25mm: 4 rounds/s, flight seconds, spread px, burst radius px and most victims. (proposal)
  // The Viper fires continuously.
  mg: { rate: 4, travel: 0.07, spread: 5, splash: 7, victims: 4 },
  // 105mm: reload, flight time, kill radius, hurt radius (a hurt walker dies too, a brute may not),
  // and how close to the train a blast hurts the train too
  he: { reload: 2.4, travel: 0.7, kill: 34, hurt: 56, close: 28 },
  // The global living limit. Individual leg populations and enemy introductions are in legs.js.
  pop: { max: 1100 },
  // Seconds before a grabbed survivor is lost, for the retained full-game survivor helpers.
  station: { grab: 1.4 },
  // Share of each zombie's scrap value paid now; fractions wait in the kill pot. (proposal)
  pay: { kill: 1 },
  // Dead Wall health, rail placement/standoff, collectible scrap, warning/clearance and crash bodies. (proposal)
  wall: { hp: 75, ahead: 180, stop: 20, loot: 40, warn: 300, len: 48, goalPad: 40, bodies: 6,
    half: 34, depthY: 29 // Cached actor's ground feet span x7..71 and y17..46, behind its face. (proposal)
  },
  // bought in the skill tree. The rail cannon (cannon.js): seconds to reload, seconds each GUN SPEED
  // level takes off, px either side of its line that it kills, how fast its barrel turns (radians/s).
  gun: { reload: 4, fast: 0.5, hw: 5, turn: 7 },
  // The Turbo Ram: top speed (px/s), seconds at it, seconds to get up to it and to ease back, the
  // hit zone (px either side of the rail middle, px behind and ahead of the nose), cooldown seconds,
  // the next stop nearer than noStart px = it can't start, nearer than cut px = it ends
  // (250 and 200 m), px the camera leads, and its kills pay ×pay.
  ram: { speed: 120, dur: 2, cooldown: 20, rise: 0.4, ease: 1, band: 16, back: 10, front: 8, noStart: 500, cut: 400,
    lead: 40, pay: 2,
    damage: 3, bandGrowth: 6, shove: 70, clearance: 3, shockR: 40, shockT: 0.35 // (proposal)
  },
  // Seconds the built-in winch needs over a survivor: about 2 s. (proposal)
  winch: { hover: 2 },
  // dps = damage to the train each second while it holds on
  types: [
    { hp: 2, speed: [15, 20], value: 1, dps: 0.25 },               // walker: 2 base gun hits (proposal)
    { hp: 1, speed: [42, 52], value: 1, dps: 0.3, run: true },     // runner
    { hp: 6, speed: [10, 13], value: 5, dps: 2, big: true }        // brute

// heliweap.js - the Viper's automatic weapons. A nose-gun shot can become a rocket, with a short
// smoke trail and an area blast. Projectiles carry their own numbers and world launch position.
// Friendly blasts use zombie damage helpers only, so they cannot hurt the train.

const HWC = {
  // Seconds without a rocket before the next nose-gun shot must become one.
  rocketWait: 6,
  // Flight seconds, blast radius/damage, arc height, smoke lifetime and hot streak spacing (proposal)
  rocket: { travel: 0.25, radius: 16, damage: 6, arc: 12, smokeLife: [0.4, 0.6], streakStep: 0.005 },
  // Ground range, launch/retry seconds, spread/mount px, flash seconds/glow and burn DPS (proposal)
  pod: { range: 180, gap: 0.08, retry: 0.25, spread: 8, mountX: 11, mountY: -9, flash: 0.07, flashRadius: 8, burnDps: 2 },
  // Ground range/damage/radius, flight/arc/curve, retry seconds, mount px and trail timing (proposal)
  hellfire: { range: 220, damage: 18, radius: 30, travel: 0.8, arc: 28, curve: 18,
    retry: 0.25, mountX: 8, mountY: -8, smokeLife: [0.4, 0.6], streakStep: 0.015 }
};
// Lazy run state also works behind the title: a new G starts fresh counters without touching SAVE.

// cars.js - automatic weapons mounted on the existing train cars. Art is baked before the atlas
// warms; runtime state belongs to one G and never keeps zombie references between shots.
// Hooks: updateTrainWeapons (step), drawTrainWeapon (drawCar), drawTrainWeaponFx (additive pass).
const MGC = {
  car: 3, headings: 32, rate: 2, scale: 0.6, flash: 0.07,
  damage: 1, range: 100, wallRange: 200, barrel: 8, barrelZ: 2, halfWidth: 3, recoil: 1.3, recoilDecay: 12 // (proposal)
};
const MG_OFFSETS = [[0], [-7, 7], [-9, 0, 9]];
const MGART = { n: [], h: [], bn: [], bh: [] };
const MGCAR = { g: null, mg: null };
// Independent rocket range/payload, flight seconds/height, launch/retry timing and spread (proposal)
const KATC = { car: 2, deck: 3, headings: 32, damage: 8, radius: 24, range: 300,
  travel: 0.8, arc: 32, gap: 0.08, retry: 0.25, spread: 12, split: 0.65,
  tubeFront: 9, muzzleZ: 4, flash: 0.07,
  cluster: { damage: 4, radius: 12, fall: 0.3, spread: 12 } };
const KAT_TUBES = [-5, -3, -1, 1, 3, 5], KATART = { n: [], h: [] };

// gadgets.js - hot steam clears climbers, then its optional cloud follows the train for two seconds.
// Each burst has one receipt per zombie, shared with its cloud. Steam uses ordinary white smoke
// particles and zombie damage helpers, never fire, scorch or train damage.
// Hooks: updateGadgets (step, after updateZombies); steamState (read-only run diagnostics).

// Base damage/ground reach, puff spacing/count, minimum emitter height and particle tuning (proposal)
const STEAMC = { damage: 2, interval: 5, reachStep: 6, wallReach: 24, cloudBase: 6, cloudDuration: 2,
  puffGap: 0.25, puffsPerVent: 2, refreshPuffs: 1, ventAcross: 8, ventZ: 3,
  life: [0.5, 0.75], size: [2, 3], grow: 8, growPerLevel: 3, sideSpeed: [24, 40], rise: [25, 45], carry: 0.45, drag: 2.6,
  colors: ['rgba(240,240,232,0.65)', 'rgba(214,218,214,0.5)'] };

// air.js - plane slots, charges, aiming and the reserved band below the world.
// Ownership and upgrades are fixed when a leg starts; flight and damage stay in planes.js.
const AIRBAND = { height: 18 }; // Band height in game px.
// Starting cooldowns and floors are seconds; payloads enable at their own tasks.
const PLANES = {
  a10: { name: 'A-10', cooldown: 25, floor: 12, available: true },
  f4: { name: 'F-4', cooldown: 30, floor: 15, available: true },
  b52: { name: 'B-52', cooldown: 45, floor: 25, available: true },
  b2: { name: 'B-2', cooldown: 60, floor: 40, available: false }
};
// Double-tap seconds, slot width/gap/left px, return-animation seconds, and crowd radius px (proposal).
const AIRCFG = { doubleTap: 0.35, slotWidth: 78, slotGap: 4, left: 6, returnTime: 0.25, crowdRadius: 40 };

// planes.js - plane flights and payloads. The shared air.js framework owns keys, aiming, charges
// and cooldowns; this file only launches and updates the actual planes, bombs and glowing hits.
// The A-10 flies one pass, with parallel gun bands and an optional four-bomb finish.

// speed = px/s, alt = height (px) as it comes in, dive = px lower while it fires, len = px of
// ground it strafes, lead = px ahead of the jet its rounds land, step = px between two hits you see
// (a puff of fire every 3rd, a big blast every 8th), half / dmg = the band and the damage before upgrades, bombR = px
// a bomb kills round it
const JETC = { speed: 320, alt: 46, dive: 12, len: 230, lead: 44, step: 4, half: 13, dmg: 3, bombR: 34, N: 32,
  // Centre spacing leaves four pixels between the original gun bands (proposal)
  lineGap: 30,
  // Seconds of ground-marker anticipation, then shadow entry before the body appears (proposal)
  showDelay: 0.3, shadowLead: 0.1 };

// f4.js - the swept-wing F-4 and its line of burning ground. Flight/show state stays in STRAF.
// Hooks: f4Payload/f4Fire (plane launch/update), drawFireLine (air aim), planeArt (body/shadow).
const F4C = {
  // Base fire-line length, DPS, patch radius/spacing and filled-preview opacity (proposal)
  length: 230, damage: 2, radius: 14, step: 18, previewAlpha: 0.16
};

// b52.js - the eight-engine bomber and its row of falling bombs. Flights live in STRAF.
// Hooks: b52Payload/b52Drop (plane launch/update), drawBombLane (air aim), planeArt (body/shadow).
const B52C = {
  // Lane length, blast radius/damage, fall seconds, fire seconds/DPS and preview opacity (proposal)
  length: 300, radius: 18, damage: 12, fall: 0.55, burnDuration: 4, burnDamage: 2, previewAlpha: 0.12
};

// b2.js - a flying wing and one huge, train-safe blast. The finale gift enables its slot later.
// Hooks: b2Payload/b2Drop/b2Impact (planes), drawB2Circle (aim), planeArt (normal/shadow/thermal).
const B2C = {
  // Ground radius, fall seconds, largest core radius/cap/time, ring ratio/times, preview opacity (proposal)
  radius: 65, fall: 0.7, coreRadius: 44, coreCap: 20, coreTime: 1.1,
  outerRing: 1.5, ringTime: 0.35, dustTime: 0.7, previewAlpha: 0.1,
  // Huge-blast shake, hit-stop seconds, and thermal body brightness (proposal)
  shake: 0.9, stop: 0.08, heat: 150
};

// fire.js - burning ground shared by Napalm and planes; Fire Walls also stop walking zombies.
// Hooks: updateBurn (step), drawBurn/drawBurnFx (render), blockBurnWall (updateZombies).
// Each patch has its own damage cadence. Overlapping patches stack, and only zombies take hits.
const BURNC = {
  step: 0.25,
  // Patch cap, flame count/spread, final fade seconds and glow radius/opacity/flicker (proposal)
  cap: 60, flames: 7, spread: 0.6, fade: 0.35, glow: 1.5, alpha: 0.38, flicker: 0.08,
  // Zombie body padding outside a blocking patch, in ground px (proposal)
  wallPad: 2, wallBrutePad: 3

// loot.js - timeline finds: scrap piles on wrecks and supply crates in burnt farms. Fly the Viper
// near a find to collect it; it flies up to the heli and pays. Golden crates bank at pickup.
// Field rescues bank after a two-second hover and carry forward until saved. G.loot resets per leg.

// pile: scrap paid. crate: its guards, how near the heli wakes them,
// how near the heli its edge arrow shows, how far along the rails ahead of the train its guards are
// placed. gold: first gold payment / retry scrap, arrow reach. sos: hover reach and arrow reach.
// sos.reach = px the heli must hover within for the Winch. fly = seconds a find takes to fly
// up to the heli. Leg events supply the position and can override scrap paid.
const LOOT = {
  pile: { pay: 15 },
  crate: { pay: 50, guards: 8, wake: 120, arrow: 450, place: 500 },
  gold: { pay: 5, scrap: 25, arrow: 700 },
  sos: { reach: 20, arrow: 700 },
  fly: 0.3
};
// Event placement distances/margins in world or screen px; widthFrac is a viewport fraction (proposal)
const LEGLOOTC = { ahead: 120, off: 100, maxAhead: 500, minOff: 24, maxOff: 180, widthFrac: 0.4,
  goalPad: 40, startPad: 24, viewX: 40, viewTop: 56, viewBottom: 42 };
const RESCUE_IDS = ['rescue-4', 'rescue-8', 'rescue-10'];
// Carry placements in world px; rope/lift/icon durations in seconds; ground hand/label height in px. (proposal)
const RESCUEC = { carryAhead: 80, carryStep: 60, carryOff: 70, rope: 0.45, lift: 1.6, icon: 0.8, hand: 9, label: 22 };

// skills.js - scheduled golden runners and their rewards, the dormant cow catcher, and armor.
// Also the 25mm's kill feel: a short hit-stop when one round kills 3 or more.

const SK = {
  // Gold payout/replay scrap, crossing speed/edge margin, screen lane, bounded tracking and Hunt gaps. (proposal)
  gold: { reward: 1, scrap: 10, speed: 60, edge: 18, lane: 0.2, laneTop: 48, laneBottom: 42,
    follow: 180, ahead: 80, huntGap: 8 }
};

// audio.js - all sound, made live with the Web Audio API (no sound files). The engine follows
// Ball x Archers: audioInit builds the graph (master -> compressor, plus a light reverb), voice and
// gap limit how often a sound can play, tone and nz make one synth note or one noise burst.
// SFX holds every game sound; drone() is the helicopter's rotor under everything.

const Au = { ctx: null, master: null, noise: null, muted: false, last: {}, hum: null, roar: null,
  cues: {}, scheduledSources: 0 };
// Audio voice/gap limits use wall time. Their random draws must never advance combat's RNG.
const audioRandom = mulberry(0xa0d10);
const audioRnd = (a, b) => b === undefined ? audioRandom() * a : a + audioRandom() * (b - a);
// Ready swoosh: gate ms, burst/note seconds, volumes and rising filter/note frequencies (proposal)
const PLANE_READY_SFX = { gap: 90, life: 0.22, volume: 0.065, from: 500, to: 2300,
  q: 0.7, note: 380, noteEnd: 740, noteLife: 0.16, noteVolume: 0.012 };
// Flyover roar: simultaneous voices, seconds, volumes and falling filter/note frequencies (proposal)
const PLANE_ROAR_SFX = { voices: 2, life: 1.2, volume: 0.12, from: 2200, to: 160,
  q: 0.8, note: 180, noteEnd: 50, noteVolume: 0.03 };
// New cue gates (ms), voice counts, seconds, gains and Hz; lighter MG, rewards and heavy blasts. (proposal)
const NEW_SFXC = {
  mgCar: { gap: 70, voices: 3, life: 0.075, volume: 0.045, from: 2200, to: 650,
    note: 220, noteLife: 0.045, noteVolume: 0.014, noteEnd: 85 },
  silver: { gap: 90, voices: 2, life: 0.22, note: 1760, noteEnd: 2640, volume: 0.022 },
  f4Ignite: { gap: 160, voices: 2, life: 0.38, volume: 0.055, from: 1700, to: 250,
    note: 180, noteLife: 0.25, noteVolume: 0.018, noteEnd: 65 },
  b2Boom: { gap: 300, voices: 1, life: 1.8, volume: 0.32, from: 700, to: 35,
    note: 38, noteLife: 1.4, noteVolume: 0.22, noteEnd: 20 },
  ramShock: { gap: 200, voices: 2, life: 0.42, volume: 0.1, from: 1200, to: 100,
    note: 96, noteLife: 0.32, noteVolume: 0.07, noteEnd: 35 }
};
// Repeated pickups, chimes and steam share bounded copies rather than building a noisy crowd. (proposal)
const SFX_LIMITS = {
  hiss: { gap: 100, voices: 2, life: 1.6 }, gold: { gap: 100, voices: 2, life: 0.32 },
  lootUp: { gap: 60, voices: 3, life: 0.22 }, crate: { gap: 90, voices: 2, life: 0.3 },
  golden: { gap: 150, voices: 2, life: 0.65 }, winch: { gap: 200, voices: 2, life: 0.5 },
  saved: { gap: 120, voices: 2, life: 0.22 }
};

// legs.js - the Farmlands route: one short ride between each pair of stops. This table is the
// source for the route map, station rewards and timed events. Leg numbers shown to players are 1..12.

// Rail px between stations: about 60 s at the train's 40 px/s cruise. (proposal)
const LEG_LENGTH = 2400;
// First-pass scrap targets from the final design; ordinary kill shares are tuned with real rides.
const LEG_SCRAP_TARGETS = [80, 95, 115, 135, 160, 190, 225, 265, 310, 365, 430, 500];
// Ordinary kill multipliers preserve the large hordes; wall drops remain collectible. (proposal)
const LEG_ORDINARY_PAY = [0.67831, 0.884, 0.75047, 0.66879, 0.37451, 0.47, 0.74115, 0.54759, 0.80347, 0.60226, 0.56248, 0.14645];
const LEG_WALL_PAY = { 5: 40, 9: 40 };
// The closed-gate hold lasts 30 play seconds. Standoff/rear spread px and peak-gift seconds are proposals.
const FINALEC = { hold: 30,
  stop: 20, giftAt: 15, rearOff: 40 // (proposal)
};
// Hold-relative wave clocks and sizes; every wave enters through all four viewport edges. (proposal)
const FINALE_EVENTS = [
  [0, 'wave', { n: 24, edges: [-1, 1, 0, 2] }],
  [8, 'wave', { n: 30, edges: [-1, 1, 0, 2] }],
  [15, 'wave', { n: 38, edges: [-1, 1, 0, 2] }],
  [23, 'wave', { n: 30, edges: [-1, 1, 0, 2] }]
];
const STOPS = [
  Object.assign(DEPOT, { kind: 'big', side: 1 }),
  { id: 'millbrook', name: 'MILLBROOK', kind: 'big' },
  { id: 'cornfield', name: 'CORNFIELD HALT', kind: 'small' },
  { id: 'redbarn', name: 'RED BARN', kind: 'big' },
  { id: 'silo', name: 'SILO JUNCTION', kind: 'small' },
  { id: 'oldmill', name: 'OLD MILL', kind: 'big' },
  { id: 'pumpkin', name: 'PUMPKIN HALT', kind: 'small' },
  { id: 'crossroads', name: 'CROSSROADS', kind: 'big' },
  { id: 'water', name: 'WATER TOWER', kind: 'small' },
  { id: 'haybale', name: 'HAYBALE CAMP', kind: 'big' },
  { id: 'windmill', name: 'WINDMILL HALT', kind: 'small' },
  { id: 'grain', name: 'GRAIN ELEVATOR', kind: 'big' },
  { id: 'terminus', name: 'FARMLANDS TERMINUS', kind: 'end' }
];
// Actual run eligibility also applies to old-leg replays after buying Hunt upgrades.
const LEG_INTRO = { runner: 2, gold: 3, silver: 4, brute: 6, boom: 7 };
const legAllows = (kind) => !G.demo && G.leg >= LEG_INTRO[kind];

// Living caps, base stream sizes/cadence and type shares; final scrap tuning is separate. (proposal)
// [want, size, gap, runner share, brute share, rail brute share]
const LEG_BASE_ROWS = [
  [160, 4, 4, 0, 0, 0], [180, 4, 3.9, 0.08, 0, 0], [210, 5, 3.8, 0.12, 0, 0],
  [240, 5, 3.7, 0.14, 0, 0], [280, 6, 3.6, 0.16, 0, 0], [340, 7, 3.5, 0.18, 0.02, 0.05],
  [400, 8, 3.4, 0.20, 0.03, 0.06], [470, 9, 3.3, 0.22, 0.04, 0.07], [540, 10, 3.2, 0.23, 0.05, 0.08],
  [620, 11, 3.1, 0.25, 0.07, 0.10], [700, 12, 3, 0.27, 0.09, 0.12], [800, 14, 2.9, 0.30, 0.12, 0.15]
];
// Event clocks, crowd sizes and scrap placements/value; special tuples stay deferred until their
// real handlers exist. Leg 9's two events at 27 s deliberately overlap. (proposal)
const legPile = (pay) => ({ ahead: 120, off: 100, side: 1, pay });
const LEG_EVENT_ROWS = [
  [[3, 'railCrowd', { n: 6 }], [12, 'stream', { edge: -1, n: 12 }], [22, 'pile', legPile(24)],
    [32, 'stream', { edge: 1, n: 14 }], [42, 'railCrowd', { n: 8 }], [52, 'wave', { n: 10 }]],
  [[3, 'railCrowd', { n: 10 }], [12, 'stream', { edge: -1, n: 18, type: 1 }], [22, 'pile', legPile(29)],
    [32, 'stream', { edge: 1, n: 20 }], [42, 'railCrowd', { n: 12 }], [52, 'wave', { n: 12 }]],
  [[3, 'railCrowd', { n: 12 }], [11, 'stream', { edge: -1, n: 22 }], [19, 'golden', { edge: -1 }],
    [27, 'pile', legPile(35)], [35, 'stream', { edge: 1, n: 24 }], [43, 'railCrowd', { n: 16 }], [51, 'wave', { n: 14 }]],
  [[3, 'railCrowd', { n: 14 }], [11, 'stream', { edge: -1, n: 24 }], [19, 'golden', { edge: 1 }],
    [27, 'rescue', { id: 'rescue-4' }], [35, 'pile', legPile(41)], [43, 'silverGroup', { n: 3, edge: 1 }], [51, 'wave', { n: 16 }]],
  [[3, 'railCrowd', { n: 18 }], [11, 'stream', { edge: -1, n: 26 }], [19, 'golden', { edge: -1 }],
    [27, 'deadWall', {}], [35, 'pile', legPile(48)], [43, 'stream', { edge: 1, n: 28 }], [51, 'wave', { n: 18 }]],
  [[3, 'railCrowd', { n: 20, leaders: 1, leadType: 2 }], [11, 'stream', { edge: -1, n: 30 }], [19, 'golden', { edge: 1 }],
    [27, 'goldCrate', {}], [35, 'pile', legPile(57)], [43, 'stream', { edge: 1, n: 32 }], [51, 'wave', { n: 20 }]],
  [[3, 'explosiveStream', { edge: -1, n: 8 }], [11, 'stream', { edge: 1, n: 34 }], [19, 'golden', { edge: -1 }],
    [27, 'crate', legPile(38)], [35, 'pile', legPile(30)], [43, 'railCrowd', { n: 24 }], [51, 'wave', { n: 24 }]],
  [[3, 'railCrowd', { n: 26 }], [11, 'golden', { edge: 1 }], [19, 'rescue', { id: 'rescue-8' }],
    [27, 'pile', legPile(80)], [35, 'goldCrate', {}], [43, 'silverGroup', { n: 4, edge: 1 }], [51, 'wave', { n: 40, big: true }]],
  [[3, 'railCrowd', { n: 30 }], [11, 'stream', { edge: -1, n: 40 }], [19, 'golden', { edge: -1 }],
    [27, 'stream', { edge: 1, n: 40 }], [27, 'deadWall', {}], [35, 'pile', legPile(93)], [43, 'goldCrate', {}], [51, 'wave', { n: 44, big: true }]],
  [[3, 'stream', { edge: 0, n: 26, leaders: 2, leadType: 2, type: 1 }], [11, 'railCrowd', { n: 34 }], [19, 'golden', { edge: 1 }],
    [27, 'rescue', { id: 'rescue-10' }], [35, 'pile', legPile(110)],
    [43, 'stream', { edge: 0, n: 30, leaders: 3, leadType: 2, type: 1 }], [51, 'wave', { n: 48, big: true }]],
  [[3, 'railCrowd', { n: 40 }], [11, 'stream', { edge: -1, n: 50 }], [19, 'golden', { edge: -1 }],
    [27, 'goldCrate', {}], [35, 'pile', legPile(129)],
    [43, 'stream', { edge: 0, n: 50, leaders: 4, leadType: 2, type: 1 }], [51, 'wave', { n: 65, big: true }]],
  [[3, 'wave', { n: 65, big: true }], [11, 'stream', { edge: -1, n: 60 }], [19, 'golden', { edge: 1 }],
    [27, 'goldCrate', {}], [35, 'pile', legPile(150)], [43, 'railCrowd', { n: 50 }], [51, 'wave', { n: 75, big: true }]]
];
const LEGS = [];
for (let n = 1; n < STOPS.length; n++) {
  const from = STOPS[n - 1], to = STOPS[n];
  to.km = from.km + LEG_LENGTH / CFG.line.km;
  to.side = n % 2 ? 1 : -1;
  const b = LEG_BASE_ROWS[n - 1], base = HORDE[n - 1];
  Object.assign(base, { want: b[0], size: b[1], gap: b[2], run: b[3], brute: b[4], railBrute: b[5] });
  LEGS.push({ n, from, to, len: LEG_LENGTH, stars: n >= 3, base: HORDE[n - 1],
    scrapTarget: LEG_SCRAP_TARGETS[n - 1], ordinaryPay: LEG_ORDINARY_PAY[n - 1], wallPay: LEG_WALL_PAY[n] ?? CFG.wall.loot,
    rescue: [4, 8, 10].includes(n) ? 'rescue-' + n : null, finale: n === 12, events: LEG_EVENT_ROWS[n - 1] });
}
const legDef = (n) => LEGS[n - 1] || null;
// Scenery uses the same complete line on every retry, so cached ground stays consistent.
const STATIONS = STOPS.slice(1);

// Brief title-only event notice; streams already have their own edge marks. (proposal)
const LEG_EVENT_NOTICE = 1.8;
